"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["79880"],{56033(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.alteracao_quebra_regra_de_aplicabilidade","status":422,"titulo":"A altera\xe7\xe3o deixaria de valer a regra de aplicabilidade de uma modalidade"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.alteracao_quebra_regra_de_aplicabilidade","requisitos":["UNI-REQ-0159"],"oQueAconteceu":["O administrador enviou a nova defini\xe7\xe3o de um fato do cat\xe1logo (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`), mas a regra de aplicabilidade de uma modalidade cita este fato, e a defini\xe7\xe3o nova a deixaria inv\xe1lida, por exemplo ao trocar o tipo de dado em que a condi\xe7\xe3o se apoia. A recusa considera apenas os problemas causados pela altera\xe7\xe3o: uma regra que j\xe1 era inv\xe1lida antes n\xe3o impede a altera\xe7\xe3o. A corre\xe7\xe3o da defini\xe7\xe3o de um fato \xe9 regra do UNI-REQ-0159, e a API recusa a altera\xe7\xe3o que deixaria inv\xe1lido algo que j\xe1 cita o fato, em vez de alter\xe1-lo em sil\xeancio. Nada \xe9 gravado: o fato continua com a defini\xe7\xe3o anterior.","A recusa vem na lista `errors` da resposta, com `field` igual a `citacoes.modalidades.<c\xf3digo da modalidade>`, uma entrada por modalidade afetada. A mensagem cita o que deixaria de valer."],"comoResolver":["Escolha uma das sa\xeddas. Ajuste a regra de aplicabilidade da modalidade citada para que ela valha com a defini\xe7\xe3o nova, ou retire dela a condi\xe7\xe3o que cita este fato, e reenvie a altera\xe7\xe3o; ou escolha uma defini\xe7\xe3o que a mantenha v\xe1lida. Todas as modalidades vivas s\xe3o conferidas, sem exce\xe7\xe3o: s\xf3 a modalidade exclu\xedda deixa de ser conferida.","A defini\xe7\xe3o corrigida vale para os rascunhos e para os processos novos; a vers\xe3o j\xe1 publicada de um processo n\xe3o muda."],"ondeAparece":["Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);